`timescale 1ns / 1ps

//
// Testbench for top::SpiFlashController.
//
// Prompts the controller to perform a read from a fixed address,
// emulates a simple SPI flash device on the `spi` socket, and waits
// for the result to come back on `read_data`.
//
// Conventions (matching the DUT as generated by `vir build`):
//
//   * `read_addr` is a Valid[Word[24]], packed as {valid, addr[23:0]}.
//   * `read_data` is a Valid[Word[32]], packed as {valid, data[31:0]}.
//   * `spi.cs` is asserted HIGH while a transaction is in progress,
//     and LOW while the controller is idle.
//   * The controller shifts out a command byte (0x03 = READ) followed
//     by a 24-bit address, MSB first, and expects 32 bits of data back.
//
// The flash model samples MOSI (`spi.do`) on rising edges of `spi.clk`,
// and drives MISO (`spi.di`) on falling edges.
//

module spi_flash_tb;

    localparam [23:0]   READ_ADDR    = 24'h00_12_34;
    localparam [31:0]   FLASH_WORD   = 32'hDEAD_BEEF;

    localparam [7:0]    CMD_READ     = 8'h03;

    // 8 command bits + 24 address bits + 32 data bits
    localparam integer  TOTAL_BITS   = 64;

    // Cycle-count guard for each wait loop.
    localparam integer  TIMEOUT_CYCLES = 20_000;

    localparam integer  TIMEOUT_NS = 200_000;

    //
    // DUT connections
    //

    reg         clock;
    reg         read_addr_valid;
    reg  [23:0] read_addr_payload;
    wire        device_ready;
    wire        read_data_valid;
    wire [31:0] read_data_payload;

    wire        spi_clk;
    wire        spi_cs;
    wire        spi_do;
    reg         spi_di;

    \top::SpiFlashController dut (
        .clock(clock),
        .device_ready(device_ready),
        .read_addr({read_addr_valid, read_addr_payload}),
        .read_data({read_data_valid, read_data_payload}),
        .\spi.clk (spi_clk),
        .\spi.cs (spi_cs),
        .\spi.do (spi_do),
        .\spi.di (spi_di)
    );

    initial clock = 1'b0;
    always #5 clock = ~clock;

    //
    // SPI flash behavioral model
    //

    integer     bits_received;
    reg [31:0]  shift_in;
    reg [7:0]   cmd;
    reg [23:0]  addr;

    integer     bits_sent;
    reg [31:0]  shift_out;

    initial begin
        spi_di        = 1'b0;
        bits_received = 0;
        bits_sent     = 0;
        shift_in      = 32'h0;
        shift_out     = FLASH_WORD;
        cmd           = 8'h00;
        addr          = 24'h0;
    end

    // Transaction start: reset the model state.
    always @(negedge spi_cs) begin
        bits_received = 0;
        bits_sent     = 0;
        shift_in      = 32'h0;
        shift_out     = FLASH_WORD;
        cmd           = 8'h00;
        addr          = 24'h0;
    end

    // Sample MOSI on rising edges of spi.clk while the transaction is active.
    always @(posedge spi_clk) begin
        if (!spi_cs) begin
            shift_in      = {shift_in[30:0], spi_do};
            bits_received = bits_received + 1;

            if (bits_received == 8) begin
                cmd = shift_in[7:0];
            end
            if (bits_received == 32) begin
                addr = shift_in[23:0];
            end
        end
    end

    // Drive MISO on falling edges of spi.clk once the command and
    // address have been received, MSB first.
    always @(negedge spi_clk) begin
        if (!spi_cs && bits_received >= 32 && bits_sent < 32) begin
            spi_di    = shift_out[31];
            shift_out = {shift_out[30:0], 1'b0};
            bits_sent = bits_sent + 1;
        end
    end

    //
    // Watchdog: never let the simulation hang forever.
    //
    initial begin
        #TIMEOUT_NS;
        $fatal(1, "FAIL: Timed out after %0d ns without the read completing", TIMEOUT_NS);
    end

    //
    // Main sequence
    //

    integer n;

    initial begin
        $dumpfile("build/spi_flash_tb.vcd");
        $dumpvars(0, spi_flash_tb);

        read_addr_valid   = 1'b0;
        read_addr_payload = 24'h0;

        // Let the controller come out of reset.
        repeat (5) @(posedge clock);

        if (device_ready !== 1'b1) begin
            $fatal(1, "FAIL: device_ready not asserted before the first read request");
        end
        $display("[%0t] device_ready asserted; prompting read from 0x%06h", $time, READ_ADDR);

        // Prompt the read.
        @(posedge clock);
        read_addr_valid   <= 1'b1;
        read_addr_payload <= READ_ADDR;
        @(posedge clock);
        read_addr_valid   <= 1'b0;

        // Wait for the controller to start the SPI transaction.
        n = 0;
        while (spi_cs === 1'b1) begin
            @(posedge clock);
            n = n + 1;
            if (n > TIMEOUT_CYCLES) begin
                $fatal(1, "FAIL: No SPI transaction started after %0d cycles", n);
            end
        end
        $display("[%0t] SPI transaction started (cs asserted)", $time);

        // Wait for the controller to finish the transaction.
        n = 0;
        while (spi_cs === 1'b0) begin
            @(posedge clock);
            n = n + 1;
            if (n > TIMEOUT_CYCLES) begin
                $fatal(1, "FAIL: SPI transaction never finished after %0d cycles", n);
            end
        end
        $display("[%0t] SPI transaction finished", $time);

        // Sanity-check what the controller sent us.
        if (cmd !== CMD_READ) begin
            $fatal(1, "FAIL: Expected READ command 0x%02h, got 0x%02h", CMD_READ, cmd);
        end
        if (addr !== READ_ADDR) begin
            $fatal(1, "FAIL: Expected address 0x%06h, got 0x%06h", READ_ADDR, addr);
        end

        // Wait for the result to come back.
        n = 0;
        while (read_data_valid !== 1'b1) begin
            @(posedge clock);
            n = n + 1;
            if (n > TIMEOUT_CYCLES) begin
                $fatal(1, "FAIL: read_data never became valid after %0d cycles", n);
            end
        end
        $display("[%0t] read_data valid: 0x%08h", $time, read_data_payload);

        if (read_data_payload !== FLASH_WORD) begin
            $fatal(1, "FAIL: Expected 0x%08h, got 0x%08h", FLASH_WORD, read_data_payload);
        end

        $display("PASS: Read from 0x%06h returned 0x%08h", READ_ADDR, read_data_payload);
        $finish;
    end

endmodule
